var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();
return new {scene=scene.path,dirty=scene.isDirty,materials=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<UnityEngine.Renderer>(true)).Where(r=>r.GetComponent<UnityEngine.CanvasRenderer>()==null).SelectMany(r=>r.sharedMaterials.Where(m=>m!=null).Select(m=>new {obj=r.name,material=m.name,shader=m.shader.name})).GroupBy(x=>x.material+"|"+x.shader).Select(g=>new {material=g.First().material,shader=g.First().shader,objects=g.Select(x=>x.obj).Distinct().Take(3).ToArray(),count=g.Count()}).ToArray()};
